export const interfaceIconNames = Object.freeze(Object.keys(paths));

export function interfaceIconSvg(name) {
  const key = String(name || "").trim();
  if (!Object.hasOwn(paths, key)) return "";
  const filled = ["heart_filled", "play", "pause", "stop"].includes(key);
  return `<svg class="ui-ic" data-icon="${key}" viewBox="0 0 24 24" fill="${filled ? "currentColor" : "none"}" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[key]}</svg>`;
}
